package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.std.StdKeyDeserializer;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.EnumResolver;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.math.*;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.util.Calendar;
import java.util.Currency;
import java.util.Date;
import java.util.Locale;
import java.util.UUID;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;

public class StdKeyDeserializer__parse_TriageGen1Test {

    private DeserializationContext ctxt;
    private Class<?> keyClass;

    // Constants for _kind based on typical Jackson implementation patterns
    private static final int TYPE_BOOLEAN = 1;
    private static final int TYPE_BYTE = 2;
    private static final int TYPE_SHORT = 3;
    private static final int TYPE_CHAR = 4;
    private static final int TYPE_INT = 5;
    private static final int TYPE_LONG = 6;
    private static final int TYPE_FLOAT = 7;
    private static final int TYPE_DOUBLE = 8;
    private static final int TYPE_LOCALE = 9;
    private static final int TYPE_CURRENCY = 10;
    private static final int TYPE_DATE = 11;
    private static final int TYPE_CALENDAR = 12;
    private static final int TYPE_UUID = 13;
    private static final int TYPE_URI = 14;
    private static final int TYPE_URL = 15;
    private static final int TYPE_CLASS = 16;

    // Testable subclass to expose protected methods and simulate internal state
    private static class TestableKeyDeserializer extends StdKeyDeserializer {
        private final int kind;

        public TestableKeyDeserializer(int kind, Class<?> cls) {
            super(kind, cls);
            this.kind = kind;
        }

        // Overriding to allow manual setting of kind since it's used in switch
        // In a real scenario, _kind is a private field set by constructor
        // For this test, we assume the constructor sets it correctly.
        // Since we cannot change the private field of the real class, 
        // we simulate the behavior by providing a subclass that uses the kind.

        // Note: Since _kind is private in the real class, we must use the 
        // actual constructor logic. I will use a Mockito spy or a real instance.

        protected TestableKeyDeserializer(int kind, Class<?> cls, FromStringDeserializer<?> deser) {
            super(kind, cls, deser);
        }

        @Override
        protected Object _parse(String key, DeserializationContext ctxt) throws Exception {
            // This is a hack for testing purposes because _kind is private in the parent class.
            // In a real professional setting, we would use Reflection to set the private _kind field.
            return super._parse(key, ctxt);
        }
    }

    // Helper to create the deserializer using reflection to set the private _kind field
    private StdKeyDeserializer createDeserializer(int kind, Class<?> cls) throws Exception {
        StdKeyDeserializer deserializer = new StdKeyDeserializer(kind, cls) {};
        java.lang.reflect.Field kindField = StdKeyDeserializer.class.getDeclaredField("_kind");
        kindField.setAccessible(true);
        kindField.set(deserializer, kind);
        return deserializer;
    }

    @Before
    public void setUp() {
        ctxt = Mockito.mock(DeserializationContext.class);
        keyClass = String.class;
    }

    @Test
    public void testBoolean() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_BOOLEAN, Boolean.class);
        assertEquals(Boolean.TRUE, invokeParse(deserializer, "true", ctxt));
        assertEquals(Boolean.FALSE, invokeParse(deserializer, "false", ctxt));
        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new IllegalArgumentException());
        try {
            invokeParse(deserializer, "notbool", ctxt);
        } catch (IllegalArgumentException e) {
            // expected
        }
    }

    @Test
    public void testByte() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_BYTE, Byte.class);
        assertEquals(Byte.valueOf((byte) 0), invokeParse(deserializer, "0", ctxt));
        assertEquals(Byte.valueOf((byte) 127), invokeParse(deserializer, "127", ctxt));
        assertEquals(Byte.valueOf((byte) -128), invokeParse(deserializer, "-128", ctxt));
        assertEquals(Byte.valueOf((byte) 255), invokeParse(deserializer, "255", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new RuntimeException());
        try {
            invokeParse(deserializer, "256", ctxt);
        } catch (Exception e) {
            // expected overflow
        }
        try {
            invokeParse(deserializer, "-129", ctxt);
        } catch (Exception e) {
            // expected overflow
        }
    }

    @Test
    public void testShort() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_SHORT, Short.class);
        assertEquals(Short.valueOf((short) 32767), invokeParse(deserializer, "32767", ctxt));
        assertEquals(Short.valueOf((short) -32768), invokeParse(deserializer, "-32768", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new RuntimeException());
        try {
            invokeParse(deserializer, "32768", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testChar() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_CHAR, Character.class);
        assertEquals('a', invokeParse(deserializer, "a", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new RuntimeException());
        try {
            invokeParse(deserializer, "ab", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testInt() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_INT, Integer.class);
        assertEquals(123, invokeParse(deserializer, "123", ctxt));
    }

    @Test
    public void testLong() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_LONG, Long.class);
        assertEquals(123456789L, invokeParse(deserializer, "123456789", ctxt));
    }

    @Test
    public void testFloat() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_FLOAT, Float.class);
        assertEquals(1.23f, (Float) invokeParse(deserializer, "1.23", ctxt), 0.001f);
    }

    @Test
    public void testDouble() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_DOUBLE, Double.class);
        assertEquals(1.23, (Double) invokeParse(deserializer, "1.23", ctxt), 0.001);
    }

    @Test
    public void testUuid() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_UUID, UUID.class);
        String uuidStr = UUID.randomUUID().toString();
        assertEquals(UUID.fromString(uuidStr), invokeParse(deserializer, uuidStr, ctxt));
    }

    @Test
    public void testUri() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_URI, URI.class);
        String uriStr = "http://example.com";
        assertEquals(URI.create(uriStr), invokeParse(deserializer, uriStr, ctxt));
    }

    @Test
    public void testUrl() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_URL, URL.class);
        String urlStr = "http://example.com";
        assertEquals(new URL(urlStr), invokeParse(deserializer, urlStr, ctxt));
    }

    @Test
    public void testDate() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_DATE, Date.class);
        Date now = new Date();
        when(ctxt.parseDate("now")).thenReturn(now);
        assertEquals(now, invokeParse(deserializer, "now", ctxt));
    }

    @Test
    public void testCalendar() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_CALENDAR, Calendar.class);
        Date now = new Date();
        Calendar cal = Calendar.getInstance();
        cal.setTime(now);

        when(ctxt.parseDate("now")).thenReturn(now);
        when(ctxt.constructCalendar(now)).thenReturn(cal);
        assertEquals(cal, invokeParse(deserializer, "now", ctxt));

        when(ctxt.parseDate("null")).thenReturn(null);
        assertNull(invokeParse(deserializer, "null", ctxt));
    }

    @Test
    public void testClass() throws Exception {
        StdKeyDeserializer deserializer = createDeserializer(TYPE_CLASS, Class.class);
        when(ctxt.findClass("java.lang.String")).thenReturn(String.class);
        assertEquals(String.class, invokeParse(deserializer, "java.lang.String", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new RuntimeException());
        try {
            invokeParse(deserializer, "invalid.Class", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testLocaleAndCurrency() throws Exception {
        // Mocking FromStringDeserializer for Locale/Currency
        fromStringDeserializer mockDeser = Mockito.mock(fromStringDeserializer.class);
        // Note: In actual Jackson, FromStringDeserializer is an abstract class. 
        // Since we can't easily instantiate it, we use a mock.

        // For the sake of the test, we simulate the _deser field via reflection
        StdKeyDeserializer localeDeser = createDeserializerWithDeser(TYPE_LOCALE, keyClass, mockDeser);
        when(mockDeser._deserialize(eq("en_US"), any())).thenReturn("en_US");
        assertEquals("en_US", invokeParse(localeDeser, "en_US", ctxt));

        when(mockDeser._deserialize(eq("USD"), any())).thenThrow(new IOException());
        when(ctxt.weirdKeyException(any(), anyString(), anyString())).thenThrow(new RuntimeException());
        try {
            invokeParse(localeDeser, "USD", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    // Helper to invoke protected method
    private Object invokeParse(StdKeyDeserializer deserializer, String key, DeserializationContext ctxt) throws Exception {
        java.lang.reflect.Method method = StdKeyDeserializer.class.getDeclaredMethod("_parse", String.class, DeserializationContext.class);
        method.setAccessible(true);
        return method.invoke(deserializer, key, ctxt);
    }

    private StdKeyDeserializer createDeserializerWithDeser(int kind, Class<?> cls, FromStringDeserializer<?> deser) throws Exception {
        StdKeyDeserializer deserializer = new StdKeyDeserializer(kind, cls, deser) {};
        java.lang.reflect.Field kindField = StdKeyDeserializer.class.getDeclaredField("_kind");
        kindField.setAccessible(true);
        kindField.set(deserializer, kind);
        return deserializer;
    }

    // Dummy class to satisfy compiler for the mock
    private abstract static class fromStringDeserializer {
        abstract Object _deserialize(String key, DeserializationContext ctxt) throws IOException;
    }
}
